def _copy_kernel(w_ref, b_ref, w_out_ref, b_out_ref):
    w_out_ref[...] = w_ref[...]
    b_out_ref[...] = b_ref[...]


def workload(W, b):
    num_labels = W.shape[0] - 1
    hidden_size = W.shape[1]
    num_device = b.shape[1]
    block_rows = 128

    w_in = W[:-1].reshape(1, num_labels, hidden_size)
    b_in = b[:-1].reshape(1, num_labels, b.shape[1])

    grid = (num_device, num_labels // block_rows)

    def w_in_map(device, row):
        del device
        return (0, row, 0)

    def b_in_map(device, row):
        del device
        return (0, row, 0)

    def out_map(device, row):
        return (device, row, 0)

    in_specs = (
        pl.BlockSpec((1, block_rows, hidden_size), w_in_map),
        pl.BlockSpec((1, block_rows, b.shape[1]), b_in_map),
    )
    out_specs = (
        pl.BlockSpec((1, block_rows, hidden_size), out_map),
        pl.BlockSpec((1, block_rows, b.shape[1]), out_map),
    )
    out_shape = (
        jax.ShapeDtypeStruct(
            (num_device, num_labels, hidden_size), W.dtype
        ),
        jax.ShapeDtypeStruct(
            (num_device, num_labels, b.shape[1]), b.dtype
        ),
    )

    return pl.pallas_call(
        _copy_kernel,
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=in_specs,
            out_specs=out_specs,
        ),
        out_shape=out_shape,
    )(w_in, b_in)
