def _loss_kernel(preds_ref, target_ref, out_ref, acc_ref, *, channels, nsteps):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _initialize():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    preds = preds_ref[...].astype(jnp.float32)
    target = target_ref[...].astype(jnp.float32)
    preds = jnp.clip(preds, 1e-10, 1.0)
    acc_ref[...] += jnp.sum(target * preds, axis=1)

