import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _mean_min_kernel(x_ref, w_ref, b_ref, mean_ref, offset_ref,
                     mean_acc, min_acc):
    set_idx = pl.program_id(1)
    x = x_ref[0]
    activated = jnp.dot(
        x,
        w_ref[...],
        precision=lax.Precision.HIGHEST,
        preferred_element_type=jnp.float32,
    )
    activated = jax.nn.relu(activated + b_ref[...])

    @pl.when(set_idx == 0)
    def _initialize():
        mean_acc[...] = activated
        min_acc[...] = x

    @pl.when(set_idx > 0)
    def _accumulate():
        mean_acc[...] += activated
        min_acc[...] = jnp.minimum(min_acc[...], x)

    @pl.when(set_idx == pl.num_programs(1) - 1)
    def _store():
        mean_ref[...] = mean_acc[...] / pl.num_programs(1)
        offset_ref[...] = min_acc[...]


def _gated_offset_kernel(mean_ref, w_ref, b_ref, offset_ref, out_ref):
    gated = jnp.dot(
        mean_ref[...],
        w_ref[...],
        precision=lax.Precision.HIGHEST,
        preferred_element_type=jnp.float32,
    )
    gated = jax.nn.sigmoid(gated + b_ref[...])
    out_ref[...] = offset_ref[...] * gated


def workload(embeddings, w1, w2, b1, b2):
    num_sets, batch, seq, dim = embeddings.shape
    rows = batch * seq
    output_dtype = embeddings.dtype

    x = embeddings.astype(jnp.float32).reshape((num_sets, rows, dim))
    w1f = w1.astype(jnp.float32)
    w2f = w2.astype(jnp.float32)
    b1f = b1.astype(jnp.float32)
    b2f = b2.astype(jnp.float32)

    row_block = 256 if rows % 256 == 0 else rows
    row_tiles = rows // row_block

    def x_index(m, s):
        return (s, m, 0)

    def weight_index(m, s):
        return (0, 0)

    def bias_index(m, s):
        return (0,)

    def matrix_index(m, s):
        return (m, 0)

    mean, offset = pl.pallas_call(
        _mean_min_kernel,
        grid=(row_tiles, num_sets),
        in_specs=[
            pl.BlockSpec((1, row_block, dim), x_index),
            pl.BlockSpec((dim, dim), weight_index),
            pl.BlockSpec((dim,), bias_index),
        ],
        out_specs=(
            pl.BlockSpec((row_block, dim), matrix_index),
            pl.BlockSpec((row_block, dim), matrix_index),
        ),
        scratch_shapes=[
            pltpu.VMEM((row_block, dim), jnp.float32),
            pltpu.VMEM((row_block, dim), jnp.float32),
        ],
        out_shape=(
            jax.ShapeDtypeStruct((rows, dim), jnp.float32),
            jax.ShapeDtypeStruct((rows, dim), jnp.float32),
        ),
    )(x, w1f, b1f)

    def row_index(m):
        return (m, 0)

    def gate_weight_index(m):
        return (0, 0)

    def gate_bias_index(m):
        return (0,)

    result = pl.pallas_call(
        _gated_offset_kernel,
        grid=(row_tiles,),
        in_specs=[
            pl.BlockSpec((row_block, dim), row_index),
            pl.BlockSpec((dim, dim), gate_weight_index),
            pl.BlockSpec((dim,), gate_bias_index),
            pl.BlockSpec((row_block, dim), row_index),
        ],
        out_specs=pl.BlockSpec((row_block, dim), row_index),
        out_shape=jax.ShapeDtypeStruct((rows, dim), jnp.float32),
    )(mean, w2f, b2f, offset)

    return result.astype(output_dtype).reshape((batch, seq, dim))
