    elif b % 4 == 0:
        bb = 4
    elif b % 2 == 0:
        bb = 2
    else:
        bb = 1

    if d % 32 == 0:
        bd = 32
    elif d % 16 == 0:
        bd = 16
    else:
        bd = d

    grid = (b // bb, d // bd)
    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
