import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _lde_kernel(x_ref, mu_ref, s_ref, out_ref, frames):
    tile = pl.program_id(1)

    # x_tile has shape (BT, D), and mu has shape (D, C).
    x_tile = jnp.transpose(x_ref[0, :, :], (1, 0))
    mu = mu_ref[...]
    x_f32 = x_tile.astype(jnp.float32)
    mu_f32 = mu.astype(jnp.float32)

    # sum_D (x_D - mu_DC)^2
    #   = sum_D x_D^2 + sum_D mu_DC^2 - 2 * (x @ mu)_C.
    cross = jnp.dot(x_tile, mu, preferred_element_type=jnp.float32)
    x_sq = jnp.sum(x_f32 * x_f32, axis=1, keepdims=True)
    mu_sq = jnp.sum(mu_f32 * mu_f32, axis=0, keepdims=True)
    logits = (x_sq + mu_sq - 2.0 * cross) * s_ref[...].astype(jnp.float32)[None, :]

    logits = logits - jnp.max(logits, axis=1, keepdims=True)
    exp_logits = jnp.exp(logits)
    weights = exp_logits / jnp.sum(exp_logits, axis=1, keepdims=True)

    # sum_T weights_TC * (x_TD - mu_DC)
    #   = (weights^T @ x)_CD^T - mu_DC * sum_T weights_TC.
    weighted_x = jnp.dot(
        jnp.transpose(weights).astype(x_tile.dtype),
        x_tile,
        preferred_element_type=jnp.float32,
    )
    weight_sum = jnp.sum(weights, axis=0)
    contribution = jnp.transpose(weighted_x) - mu_f32 * weight_sum[None, :]

    @pl.when(tile == 0)
    def _initialize():
        out_ref[...] = jnp.zeros_like(out_ref)

    out_ref[...] += contribution

    @pl.when(tile == pl.num_programs(1) - 1)
    def _normalize():
        out_ref[...] = out_ref[...] / jnp.float32(frames)


def workload(x, mu, s):
    batch, dim, frames = x.shape
    _, centers = mu.shape

    block_frames = min(128, frames)
    while frames % block_frames != 0:
        block_frames -= 1

    def x_map(b, t):
        return (b, 0, t)

    def mu_map(b, t):
        return (0, 0)

    def s_map(b, t):
        return (0,)

    def out_map(b, t):
        return (b, 0, 0)

    result = pl.pallas_call(
        lambda xr, mr, sr, out: _lde_kernel(xr, mr, sr, out, frames),
        grid=(batch, frames // block_frames),
        in_specs=[
            pl.BlockSpec((1, dim, block_frames), x_map),
            pl.BlockSpec((dim, centers), mu_map),
            pl.BlockSpec((centers,), s_map),
        ],
        out_specs=pl.BlockSpec((1, dim, centers), out_map),
        out_shape=jax.ShapeDtypeStruct(
            (batch, dim, centers), jnp.float32
        ),
    )(x, mu, s)

    return result.astype(x.dtype).reshape(batch, dim * centers, 1)
