from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _pool_kernel(x_ref, out_ref, acc_ref, *, nsteps, spatial_size):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref.at[0, 0][...] = jnp.full(
            acc_ref.shape[-1:], -jnp.inf, dtype=jnp.float32
        )
        acc_ref.at[0, 1][...] = jnp.zeros(
            acc_ref.shape[-1:], dtype=jnp.float32
        )

    x = x_ref[0].astype(jnp.float32)
    tile_max = jnp.max(x, axis=(1, 2))
    tile_sum = jnp.sum(x, axis=(1, 2))

    acc_ref.at[0, 0][...] = jnp.maximum(acc_ref[0, 0], tile_max)
    acc_ref.at[0, 1][...] = acc_ref[0, 1] + tile_sum

    @pl.when(k == nsteps - 1)
    def _store():
        out_ref.at[0, 0][...] = acc_ref[0, 0].astype(out_ref.dtype)
        mean = acc_ref[0, 1] / jnp.asarray(spatial_size, dtype=jnp.float32)
        out_ref.at[0, 1][...] = mean.astype(out_ref.dtype)


@jax.jit
def workload(x):
    b, c, h, w = x.shape

    if c % 256 == 0:
        bc = 256
    elif c % 128 == 0:
        bc = 128
    else:
        bc = c

    if h % 16 == 0:
        bh = 16
    else:
        bh = h

    nsteps = h // bh
    grid = (b, c // bc, nsteps)

    pooled = pl.pallas_call(
        functools.partial(
            _pool_kernel,
            nsteps=nsteps,
            spatial_size=h * w,
        ),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=grid,
            in_specs=[
                pl.BlockSpec(
                    (1, bc, bh, w),
                    lambda i, j, k: (i, j, k, 0),
                )
            ],
            out_specs=pl.BlockSpec(
                (1, 2, bc),
                lambda i, j, k: (i, 0, j),
            ),
            scratch_shapes=[
                pltpu.VMEM((1, 2, bc), jnp.float32),
            ],
        ),
        out_shape=jax.ShapeDtypeStruct((b, 2, c), x.dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(x)

    return pooled.reshape((b, 2 * c, 1, 1))
