from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu


def _linear_tanh_kernel(x_ref, w_ref, b_ref, out_ref, acc_ref, *, nsteps):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        x_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(k == nsteps - 1)
    def _finish():
        value = jnp.tanh(acc_ref[...] + b_ref[...])
        out_ref[...] = value.astype(out_ref.dtype)


def _tile_size(dim, preferences):
    for size in preferences:
        if dim % size == 0:
            return size
    return dim


def _linear_tanh(x, w, b, output_dtype):
    m, k = x.shape
    n = w.shape[1]

    bm = _tile_size(m, (512, 256, 128))
    bk = _tile_size(k, (512, 256, 128))
    bn = _tile_size(n, (1024, 512, 256, 128))
    nsteps = k // bk

    return pl.pallas_call(
        functools.partial(_linear_tanh_kernel, nsteps=nsteps),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(m // bm, n // bn, nsteps),
            in_specs=[
                pl.BlockSpec((bm, bk), lambda i, j, kk: (i, kk)),
                pl.BlockSpec((bk, bn), lambda i, j, kk: (kk, j)),
                pl.BlockSpec((1, bn), lambda i, j, kk: (0, j)),
            ],
            out_specs=pl.BlockSpec((bm, bn), lambda i, j, kk: (i, j)),
            scratch_shapes=[pltpu.VMEM((bm, bn), jnp.float32)],
        ),
        out_shape=jax.ShapeDtypeStruct((m, n), output_dtype),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel", "parallel", "arbitrary")
        ),
    )(x, w, b.reshape(1, n))


def workload(x, w_enc, b_enc, w_in, b_in, w_out, b_out):
    original_shape = x.shape
    feature_size = original_shape[-1]
    m = x.size // feature_size

    h = x.reshape(m, feature_size).astype(jnp.bfloat16)
    h = _linear_tanh(
        h, w_enc.astype(jnp.bfloat16), b_enc, jnp.bfloat16
    )
    h = _linear_tanh(
        h, w_in.astype(jnp.bfloat16), b_in, jnp.bfloat16
    )
    h = _linear_tanh(
        h, w_out.astype(jnp.bfloat16), b_out, jnp.float32
    )
    return h.reshape(original_shape)
