import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _affine(a, w, b, dtype):
    p = jnp.dot(a, w, preferred_element_type=jnp.float32).astype(dtype)
    return (p + b).astype(dtype)


def _mlp_kernel(x_ref, w1_ref, b1_ref, w2_ref, b2_ref, w3_ref, b3_ref,
                w4_ref, b4_ref, w5_ref, b5_ref, out_ref):
    dtype = x_ref.dtype
    h = x_ref[...]
    h = jax.nn.relu(_affine(h, w1_ref[...], b1_ref[...], dtype))
    h = jax.nn.relu(_affine(h, w2_ref[...], b2_ref[...], dtype))
    h = jax.nn.relu(_affine(h, w3_ref[...], b3_ref[...], dtype))
    h = jax.nn.relu(_affine(h, w4_ref[...], b4_ref[...], dtype))
    out_ref[...] = _affine(h, w5_ref[...], b5_ref[...], dtype)


def workload(x, w1, b1, w2, b2, w3, b3, w4, b4, w5, b5):
    x = x.reshape(-1, w1.shape[0])
    m = x.shape[0]
    bm = 256 if m >= 256 and m % 256 == 0 else m

    def x_map(i):
        return (i, 0)

    def w_map(i):
        return (0, 0)

    def b_map(i):
        return (0,)

    def out_map(i):
        return (i, 0)

    in_specs = [
        pl.BlockSpec((bm, x.shape[1]), x_map),
        pl.BlockSpec(w1.shape, w_map),
        pl.BlockSpec(b1.shape, b_map),
        pl.BlockSpec(w2.shape, w_map),
        pl.BlockSpec(b2.shape, b_map),
        pl.BlockSpec(w3.shape, w_map),
        pl.BlockSpec(b3.shape, b_map),
        pl.BlockSpec(w4.shape, w_map),
        pl.BlockSpec(b4.shape, b_map),
        pl.BlockSpec(w5.shape, w_map),
        pl.BlockSpec(b5.shape, b_map),
    ]
    return pl.pallas_call(
        _mlp_kernel,
        grid=(m // bm,),
        in_specs=in_specs,
        out_specs=pl.BlockSpec((bm, w5.shape[1]), out_map),
        out_shape=jax.ShapeDtypeStruct((m, w5.shape[1]), x.dtype),
    )(x, w1, b1, w2, b2, w3, b3, w4, b4, w5, b5)
