import jax
from jax.experimental import pallas as pl


def _copy_kernel(x_ref, out_ref):
    out_ref[...] = x_ref[...]


def workload(x):
    batch, channels, height, width = x.shape
    size = min(2, channels)

    # A two-channel block handles both the original tensor and the appended
    # two-channel slice. Fall back to single-channel blocks for small/odd C.
    block_channels = 2 if channels % 2 == 0 and size == 2 else 1
    input_channel_blocks = channels // block_channels
    output_channels = channels + size
    output_channel_blocks = output_channels // block_channels

    block_shape = (1, block_channels, height, width)

    def input_map(b, c):
        return (b, c % input_channel_blocks, 0, 0)

    def output_map(b, c):
        return (b, c, 0, 0)

    return pl.pallas_call(
        _copy_kernel,
        out_shape=jax.ShapeDtypeStruct(
            (batch, output_channels, height, width), x.dtype
        ),
        grid=(batch, output_channel_blocks),
        in_specs=[pl.BlockSpec(block_shape, input_map)],
        out_specs=pl.BlockSpec(block_shape, output_map),
    )(x)
