import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _tile_size(size, limit):
    for tile in range(min(size, limit), 0, -1):
        if size % tile == 0:
            return tile
    return 1


def _linear_sigmoid_kernel(x_ref, w_ref, b_ref, out_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        out_ref[...] = jnp.zeros(out_ref.shape, dtype=jnp.float32)

    partial = jnp.dot(
        x_ref[...],
        w_ref[...],
        preferred_element_type=jnp.float32,
    )
    out_ref[...] = out_ref[...] + partial

    @pl.when(k == pl.num_programs(2) - 1)
    def _finish():
        result = jax.nn.sigmoid(
            out_ref[...] + b_ref[...].astype(jnp.float32)
        )
        out_ref[...] = result.astype(out_ref.dtype)


def workload(x, w, b):
    m = 1
    for size in x.shape[:-1]:
        m *= size
    k = w.shape[0]
    n = w.shape[1]

    bm = _tile_size(m, 512)
    bn = _tile_size(n, 512)
    bk = _tile_size(k, 256)

    x2 = x.reshape((m, k))
    result = pl.pallas_call(
        _linear_sigmoid_kernel,
        out_shape=jax.ShapeDtypeStruct((m, n), x.dtype),
        grid=(m // bm, n // bn, k // bk),
        in_specs=[
            pl.BlockSpec((bm, bk), lambda i, j, kk: (i, kk)),
            pl.BlockSpec((bk, bn), lambda i, j, kk: (kk, j)),
            pl.BlockSpec((bn,), lambda i, j, kk: (j,)),
        ],
        out_specs=pl.BlockSpec((bm, bn), lambda i, j, kk: (i, j)),
    )(x2, w, b)
    return result.reshape(x.shape[:-1] + (n,))
