import jax.numpy as jnp
from jax.experimental import pallas as pl


def _entropy_kernel(x_ref, out_ref):
    values = x_ref[...].astype(jnp.float32)
    partial = jnp.sum(-values * jnp.log(values), axis=1)
    step = pl.program_id(3)

    @pl.when(step == 0)
    def _initialize():
        out_ref[...] = partial

    @pl.when(step != 0)
    def _accumulate():
        out_ref[...] += partial


def _divisor_at_most(size, preferred):
    block = min(size, preferred)
    while block > 1 and size % block != 0:
        block -= 1
    return block


def workload(x):
    batch, disparity, height, width = x.shape
    block_d = _divisor_at_most(disparity, 8)
    block_h = _divisor_at_most(height, 32)
    block_w = _divisor_at_most(width, 128)

    result = pl.pallas_call(
        _entropy_kernel,
        grid=(
            batch,
            height // block_h,
            width // block_w,
            disparity // block_d,
        ),
        in_specs=[
