from jax.experimental import pallas as pl


def _shuffle_cat_kernel(a_ref, b_ref, out_ref):
    for j in range(a_ref.shape[1]):
        out_ref[0, 2 * j, :, :] = a_ref[0, j, :, :]
        out_ref[0, 2 * j + 1, :, :] = b_ref[0, j, :, :]


def workload(a, b):
    n, c, h, w = a.shape
    block_c = 8 if c % 8 == 0 else 1
    block_h = 32 if h % 32 == 0 else h

    def index_map(i, j, k, l):
        return (i, j, k, l)

    input_block = (1, block_c, block_h, w)
    output_block = (1, 2 * block_c, block_h, w)
    return pl.pallas_call(
        _shuffle_cat_kernel,
        grid=(n, c // block_c, h // block_h, 1),
        in_specs=[
            pl.BlockSpec(input_block, index_map),
            pl.BlockSpec(input_block, index_map),
        ],
        out_specs=pl.BlockSpec(output_block, index_map),
        out_shape=jax.ShapeDtypeStruct((n, 2 * c, h, w), a.dtype),
    )(a, b)
