import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _sequence_bias_kernel(x_ref, bias_ref, out_ref, seq_len):
    seq_idx = pl.program_id(0)

    @pl.when(seq_idx < seq_len)
    def copy_x():
        out_ref[...] = x_ref[...]

    @pl.when(seq_idx == seq_len)
    def write_bias():
        out_ref[...] = jnp.broadcast_to(bias_ref[...], out_ref.shape)


def workload(x, bias):
    seq_len, batch, embed_dim = x.shape

    def x_index_map(seq_idx):
        return (jnp.minimum(seq_idx, seq_len - 1), 0, 0)

    def bias_index_map(seq_idx):
        del seq_idx
        return (0,)

    def out_index_map(seq_idx):
        return (seq_idx, 0, 0)

    return pl.pallas_call(
        lambda x_ref, bias_ref, out_ref: _sequence_bias_kernel(
            x_ref, bias_ref, out_ref, seq_len
        ),
        out_shape=jax.ShapeDtypeStruct(
            (seq_len + 1, batch, embed_dim), x.dtype
        ),
        grid=(seq_len + 1,),
        in_specs=[
            pl.BlockSpec((1, batch, embed_dim), x_index_map),
            pl.BlockSpec((embed_dim,), bias_index_map),
        ],
        out_specs=pl.BlockSpec((1, batch, embed_dim), out_index_map),
    )(x, bias)
